public class LocalMountainTest{public static void main(String[]args){var g=new TerrainGraph();var base=g.add(TerrainGraph.Type.CONSTANT,0,0);base.values.put("height",96.0);var m=g.add(TerrainGraph.Type.MOUNTAIN,0,0);m.input[0]=base.id;m.values.put("x",50.0);m.values.put("z",50.0);var h=g.evaluate(256,16384,62,2024,m.id,()->false).output();if(h[128*256+128]<250||h[20*256+20]!=96)throw new AssertionError("Local mountain footprint");m.values.put("aspect",2.0);m.values.put("rotation",90.0);m.values.put("ridge",.9);var range=g.evaluate(256,16384,62,2024,m.id,()->false).output();if(range[154*256+128]<=100||range[128*256+154]!=96)throw new AssertionError("Range should follow its direction");base.values.put("height",45.0);for(float v:g.evaluate(128,16384,62,2024,m.id,()->false).output())if(v!=45)throw new AssertionError("Ocean changed");System.out.println("PASS: local mountain adds relief, distant land and ocean unchanged");}}
